import sys
import time
from playwright.sync_api import sync_playwright

URL = "http://localhost:8000/games/snakes/index.html"
SCREENSHOT_PATH = "/workspace/repro_chogan595.png"


def main():
    with sync_playwright() as p:
        browser = p.chromium.launch(
            executable_path="/usr/bin/google-chrome",
            headless=True,
        )
        page = browser.new_page(viewport={"width": 1280, "height": 800})
        page.goto(URL, wait_until="networkidle")
        page.wait_for_selector("canvas.sl-canvas")

        # Dismiss tutorial modal if present on first load
        for _ in range(10):
            scrim = page.locator(".ch-scrim")
            if scrim.count() == 0 or not scrim.first.is_visible():
                break
            btn = scrim.locator("button").last
            if btn.count() > 0 and btn.is_visible():
                btn.click()
                page.wait_for_timeout(200)
            else:
                break

        page.wait_for_selector("button.sl-die")

        # Install a rAF canvas pixel sampler to observe the actual rendered
        # board square of Red (#E5484D) and Blue (#2F6FDE) tokens on every frame.
        page.evaluate("""() => {
            window.__qaSampler = {
                active: false,
                frames: [],
                readSquare(seatColor) {
                    const cv = document.querySelector('canvas.sl-canvas');
                    if (!cv || !cv.width || !cv.height) return null;
                    const ctx = cv.getContext('2d');
                    const w = cv.width, h = cv.height;
                    const data = ctx.getImageData(0, 0, w, h).data;
                    const [tr, tg, tb] = seatColor;
                    let sx = 0, sy = 0, cnt = 0;
                    const step = 2;
                    for (let y = 0; y < h; y += step) {
                        for (let x = 0; x < w; x += step) {
                            const idx = (y * w + x) * 4;
                            const r = data[idx], g = data[idx + 1], b = data[idx + 2];
                            if (Math.abs(r - tr) <= 10 && Math.abs(g - tg) <= 10 && Math.abs(b - tb) <= 10) {
                                sx += x;
                                sy += y;
                                cnt++;
                            }
                        }
                    }
                    if (cnt < 3) return null;
                    const cx = sx / cnt;
                    const cy = sy / cnt;
                    const u = w / 10;
                    const col = Math.max(0, Math.min(9, Math.floor(cx / u)));
                    const row = Math.floor(cy / u);
                    if (row >= 10) return 0;
                    const r = 9 - row;
                    const i = (r % 2 === 1) ? (9 - col) : col;
                    return r * 10 + i + 1;
                },
                start() {
                    this.frames = [];
                    this.active = true;
                    const loop = () => {
                        if (!this.active) return;
                        this.frames.push({
                            t: performance.now(),
                            red: this.readSquare([229, 72, 77]),
                            blue: this.readSquare([47, 111, 222]),
                        });
                        requestAnimationFrame(loop);
                    };
                    requestAnimationFrame(loop);
                },
                stop() {
                    this.active = false;
                    return this.frames;
                }
            };
        }""")

        observed_rolls = []
        bug_found = False

        # Play up to 6 turns (human + bot turns) to observe rolls >= 2 for both players
        for turn_idx in range(6):
            # Determine whose turn it is by checking if die is enabled (Red/human) or disabled (Bot)
            is_human_turn = page.evaluate("""() => {
                const die = document.querySelector('button.sl-die');
                return die && !die.disabled;
            }""")

            seat_key = "red" if is_human_turn else "blue"
            start_sq = page.evaluate(
                "(k) => window.__qaSampler.readSquare(k === 'red' ? [229, 72, 77] : [47, 111, 222])",
                seat_key,
            )

            # Start rAF sampling before the roll/move
            page.evaluate("() => window.__qaSampler.start()")

            if is_human_turn:
                page.click("button.sl-die")

            # Wait for die to land (die SVG shows >= 1 circle and stops spinning)
            page.wait_for_function("""() => {
                const die = document.querySelector('button.sl-die');
                if (!die) return false;
                if (die.classList.contains('sl-die--roll')) return false;
                return die.querySelectorAll('svg circle').length >= 1;
            }""", timeout=5000)

            roll_val = page.evaluate("() => document.querySelectorAll('button.sl-die svg circle').length")

            # Wait for the move and post-move turn transition to settle:
            # Either die becomes enabled again (human's turn) or die resets to 0 circles (bot's next turn)
            # or game finishes (.ch-modal appears).
            page.wait_for_function("""() => {
                if (document.querySelector('.ch-scrim')) return true;
                const die = document.querySelector('button.sl-die');
                if (!die) return false;
                return die.querySelectorAll('svg circle').length === 0;
            }""", timeout=10000)

            frames = page.evaluate("() => window.__qaSampler.stop()")

            # Compress consecutive identical squares into a sequence of visited squares
            seq = []
            for f in frames:
                sq = f[seat_key]
                if sq is not None and (not seq or seq[-1] != sq):
                    seq.append(sq)

            observed_rolls.append({
                "turn": turn_idx,
                "player": seat_key,
                "start": start_sq,
                "roll": roll_val,
                "visited_squares": seq,
            })

            if roll_val >= 2 and start_sq is not None and start_sq + roll_val <= 100:
                expected_first = start_sq + 1
                if expected_first not in seq:
                    # Confirm we jumped from start_sq directly to start_sq + 2
                    after_start = [s for s in seq if s != start_sq]
                    if after_start and after_start[0] == start_sq + 2:
                        bug_found = True

            # Stop early if we've seen the bug on both players, or after 6 turns
            red_bug = any(
                o["player"] == "red" and o["roll"] >= 2 and (o["start"] + 1) not in o["visited_squares"]
                for o in observed_rolls if o["start"] is not None
            )
            blue_bug = any(
                o["player"] == "blue" and o["roll"] >= 2 and (o["start"] + 1) not in o["visited_squares"]
                for o in observed_rolls if o["start"] is not None
            )
            if red_bug and blue_bug:
                break

            if page.locator(".ch-scrim").count() > 0:
                break

        page.screenshot(path=SCREENSHOT_PATH)
        for o in observed_rolls:
            print(f"Turn {o['turn']} ({o['player']}): start={o['start']}, roll={o['roll']}, visited={o['visited_squares']}")

        if bug_found:
            print("BUG_PRESENT")
        else:
            print("BUG_ABSENT")

        browser.close()


if __name__ == "__main__":
    main()

