from playwright.sync_api import sync_playwright


def get_timeline_state(page):
    return page.evaluate("""() => {
        const iframe = document.querySelector('#preview');
        const doc = iframe && iframe.contentDocument;
        if (!doc) return null;
        const slider = doc.querySelector('input[type="range"]');
        const wf = doc.querySelector('#waveform');
        const sr = wf && wf.firstElementChild && wf.firstElementChild.shadowRoot;
        if (!sr) return null;
        const wrapper = sr.querySelector('[part="wrapper"]');
        const tlWrapper = sr.querySelector('[part="timeline-wrapper"]');
        const tl = sr.querySelector('[part="timeline"]');
        const notches = Array.from(sr.querySelectorAll('[part~="timeline-notch"]')).map(n => ({
            left: n.style.left,
            text: n.textContent || ''
        }));
        const labels = notches.filter(n => n.text.trim() !== '');
        return {
            sliderValue: slider ? slider.value : null,
            wrapperScrollWidth: wrapper ? wrapper.scrollWidth : null,
            tlWrapperScrollWidth: tlWrapper ? tlWrapper.scrollWidth : null,
            tlScrollWidth: tl ? tl.scrollWidth : null,
            notchCount: notches.length,
            labels: labels,
        };
    }""")


def drag_slider(page, box, start_ratio, end_ratio):
    y = box["y"] + box["height"] / 2
    start_x = box["x"] + max(2, min(box["width"] - 2, box["width"] * start_ratio))
    end_x = box["x"] + max(2, min(box["width"] - 2, box["width"] * end_ratio))
    page.mouse.move(start_x, y)
    page.mouse.down()
    page.mouse.move(end_x, y, steps=10)
    page.mouse.up()


def main():
    with sync_playwright() as p:
        browser = p.chromium.launch(executable_path="/usr/bin/google-chrome", headless=True)
        page = browser.new_page(viewport={"width": 1280, "height": 800})
        page.goto("http://localhost:9090/#timeline.js", wait_until="networkidle")

        frame = page.frame_locator("#preview")
        slider = frame.locator('input[type="range"]')
        slider.wait_for(state="visible", timeout=15000)

        # Wait until waveform & timeline notches are rendered
        page.wait_for_function("""() => {
            const iframe = document.querySelector('#preview');
            const doc = iframe && iframe.contentDocument;
            const wf = doc && doc.querySelector('#waveform');
            const sr = wf && wf.firstElementChild && wf.firstElementChild.shadowRoot;
            const tl = sr && sr.querySelector('[part="timeline"]');
            return tl && tl.children.length > 0;
        }""", timeout=15000)
        page.wait_for_timeout(500)

        initial = get_timeline_state(page)
        box = slider.bounding_box()
        assert box is not None, "Zoom slider bounding box not found"

        # Step 2: Drag zoom slider thumb all the way to the left to zoom out
        initial_ratio = (float(initial["sliderValue"]) - 10.0) / (1000.0 - 10.0)
        drag_slider(page, box, initial_ratio, 0.0)
        page.wait_for_timeout(500)
        zoomed_out = get_timeline_state(page)

        # Step 4: Drag zoom slider thumb to the right past its initial position to zoom in
        drag_slider(page, box, 0.0, 0.75)
        page.wait_for_timeout(500)
        zoomed_in = get_timeline_state(page)

        # Step 6: Drag zoom slider thumb back to the left to zoom out again, then release
        drag_slider(page, box, 0.75, 0.15)
        page.wait_for_timeout(500)
        zoomed_out_again = get_timeline_state(page)

        page.screenshot(path="/workspace/repro_wavesurfer3742.png")

        # Evaluate the report's check:
        # Bug is present if waveform wrapper rescaled horizontally, while timeline container's
        # scrollWidth and rendered time-label text/positions remained identical to pre-zoom values
        # instead of matching the updated waveform wrapper width.
        waveform_rescaled = (
            zoomed_out["wrapperScrollWidth"] != initial["wrapperScrollWidth"]
            and zoomed_in["wrapperScrollWidth"] != initial["wrapperScrollWidth"]
        )
        timeline_frozen_width = (
            zoomed_out["tlWrapperScrollWidth"] == initial["tlWrapperScrollWidth"]
            and zoomed_in["tlWrapperScrollWidth"] == initial["tlWrapperScrollWidth"]
        )
        timeline_frozen_labels = (
            zoomed_out["labels"] == initial["labels"]
            and zoomed_in["labels"] == initial["labels"]
        )
        timeline_matches_wrapper = (
            zoomed_out["tlWrapperScrollWidth"] == zoomed_out["wrapperScrollWidth"]
            and zoomed_in["tlWrapperScrollWidth"] == zoomed_in["wrapperScrollWidth"]
            and zoomed_out_again["tlWrapperScrollWidth"] == zoomed_out_again["wrapperScrollWidth"]
        )

        print("initial:", initial)
        print("zoomed_out:", zoomed_out)
        print("zoomed_in:", zoomed_in)
        print("zoomed_out_again:", zoomed_out_again)

        if waveform_rescaled and (timeline_frozen_width or timeline_frozen_labels) and not timeline_matches_wrapper:
            print("BUG_PRESENT")
        else:
            print("BUG_ABSENT")

        browser.close()


if __name__ == "__main__":
    main()

import sys
import time
from playwright.sync_api import sync_playwright

URL = "http://localhost:9090/#regions.js"
SCREENSHOT_PATH = "/workspace/repro_wavesurfer3494.png"


def main():
    save_screenshot = "--screenshot" in sys.argv

    with sync_playwright() as p:
        browser = p.chromium.launch(
            executable_path="/usr/bin/google-chrome",
            headless=True,
            args=["--no-sandbox", "--disable-dev-shm-usage"],
        )
        context = browser.new_context(viewport={"width": 1280, "height": 800})
        page = context.new_page()

        # Step 1: Navigate to regions example
        page.goto(URL, wait_until="networkidle")
        # Step 2: Reload as in report
        page.reload(wait_until="networkidle")

        # Wait for #preview iframe and wavesurfer inside it
        iframe_el = page.wait_for_selector("#preview", timeout=15000)
        frame = iframe_el.content_frame()
        assert frame is not None, "Could not get #preview content_frame"

        # Step 3: Wait for waveform and regions ('Resize me', 'Cramped region', 'Drag me')
        frame.wait_for_function(
            """() => {
                const wf = document.querySelector('#waveform');
                if (!wf || !wf.firstElementChild || !wf.firstElementChild.shadowRoot) return false;
                const shadow = wf.firstElementChild.shadowRoot;
                const canvases = shadow.querySelectorAll('.canvases canvas');
                if (canvases.length === 0) return false;
                const regions = Array.from(shadow.querySelectorAll('[part~="region"]'));
                const texts = regions.map(r => r.textContent || '');
                return texts.some(t => t.includes('Resize me'))
                    && texts.some(t => t.includes('Cramped region'))
                    && texts.some(t => t.includes('Drag me'));
            }""",
            timeout=20000,
        )
        time.sleep(0.5)

        # Step 4: Drag 'Zoom:' range slider to ~75% of the slider track
        slider = frame.locator('input[type="range"]')
        slider_box = slider.bounding_box()
        assert slider_box is not None, "Zoom slider bounding box not found"
        target_x = slider_box["x"] + slider_box["width"] * 0.75
        target_y = slider_box["y"] + slider_box["height"] / 2
        page.mouse.click(target_x, target_y)
        time.sleep(0.6)

        # Locate 'Resize me' and compute scroll position so its start is off-screen left
        # and its right edge sits near 40% of the viewport (scroll container) width.
        scroll_info = frame.evaluate(
            """() => {
                const shadow = document.querySelector('#waveform').firstElementChild.shadowRoot;
                const scroll = shadow.querySelector('.scroll');
                const regions = Array.from(shadow.querySelectorAll('[part~="region"]'));
                const resizeMe = regions.find(r => (r.textContent || '').includes('Resize me'));
                const sRect = scroll.getBoundingClientRect();
                const rRect = resizeMe.getBoundingClientRect();
                return {
                    scrollWidth: scroll.scrollWidth,
                    clientWidth: scroll.clientWidth,
                    resizeMeRightRel: rRect.right - sRect.left,
                };
            }"""
        )

        # Step 5 & 6: Scroll horizontally right so start of 'Resize me' is off-screen left
        # and its right edge sits near 40% of the scroll container width.
        desired_right_pos = scroll_info["clientWidth"] * 0.40
        target_scroll_left = max(0, scroll_info["resizeMeRightRel"] - desired_right_pos)

        frame.evaluate(
            """(sl) => {
                const shadow = document.querySelector('#waveform').firstElementChild.shadowRoot;
                const scroll = shadow.querySelector('.scroll');
                scroll.scrollLeft = sl;
            }""",
            target_scroll_left,
        )
        time.sleep(0.4)

        before_drag = frame.evaluate(
            """() => {
                const shadow = document.querySelector('#waveform').firstElementChild.shadowRoot;
                const scroll = shadow.querySelector('.scroll');
                const regions = Array.from(shadow.querySelectorAll('[part~="region"]'));
                const resizeMe = regions.find(r => (r.textContent || '').includes('Resize me'));
                const handle = resizeMe.querySelector('[part*="region-handle-right"]');
                const rRect = resizeMe.getBoundingClientRect();
                const hRect = handle.getBoundingClientRect();
                return {
                    scrollLeft: scroll.scrollLeft,
                    scrollWidth: scroll.scrollWidth,
                    clientWidth: scroll.clientWidth,
                    resizeMeWidth: rRect.width,
                    handleCenterX: hRect.left + hRect.width / 2,
                    handleCenterY: hRect.top + hRect.height / 2,
                };
            }"""
        )

        # Get iframe offset in page coordinates for page.mouse
        iframe_box = iframe_el.bounding_box()
        assert iframe_box is not None
        start_x = iframe_box["x"] + before_drag["handleCenterX"]
        start_y = iframe_box["y"] + before_drag["handleCenterY"]
        drag_dx = 80  # ~80px to the right as in check

        # Step 7: Press and drag right resize handle ~80px to the right
        page.mouse.move(start_x, start_y)
        page.mouse.down()

        scroll_positions_during_drag = []
        steps = 9
        for i in range(1, steps + 1):
            cur_x = start_x + (drag_dx * i / steps)
            page.mouse.move(cur_x, start_y)
            time.sleep(0.08)
            sl = frame.evaluate(
                "() => document.querySelector('#waveform').firstElementChild.shadowRoot.querySelector('.scroll').scrollLeft"
            )
            scroll_positions_during_drag.append(sl)

        # Release
        page.mouse.up()
        time.sleep(0.3)

        # Step 9: Observe scrollLeft and region bounds upon releasing
        after_release = frame.evaluate(
            """() => {
                const shadow = document.querySelector('#waveform').firstElementChild.shadowRoot;
                const scroll = shadow.querySelector('.scroll');
                const regions = Array.from(shadow.querySelectorAll('[part~="region"]'));
                const resizeMe = regions.find(r => (r.textContent || '').includes('Resize me'));
                const cramped = regions.find(r => (r.textContent || '').includes('Cramped region'));
                const rRect = resizeMe.getBoundingClientRect();
                return {
                    scrollLeft: scroll.scrollLeft,
                    scrollWidth: scroll.scrollWidth,
                    resizeMeStyleRight: resizeMe.style.right,
                    resizeMeWidth: rRect.width,
                    crampedStyleLeft: cramped ? cramped.style.left : null,
                };
            }"""
        )

        if save_screenshot:
            page.screenshot(path=SCREENSHOT_PATH)

        # Evaluate bug conditions:
        # 1) scrollLeft jumped to 0 during drag or upon release when it was > 100 before drag
        scroll_jumped_to_zero_on_release = (
            before_drag["scrollLeft"] > 100 and after_release["scrollLeft"] <= 5
        )
        scroll_jumped_to_zero_during_drag = (
            before_drag["scrollLeft"] > 100
            and any(sl <= 5 for sl in scroll_positions_during_drag)
        )

        # 2) 'Resize me' over-expanded far past the dragged ~80px
        width_delta = after_release["resizeMeWidth"] - before_drag["resizeMeWidth"]
        resize_me_right_pct = float(after_release["resizeMeStyleRight"].replace("%", ""))
        cramped_left_pct = (
            float(after_release["crampedStyleLeft"].replace("%", ""))
            if after_release["crampedStyleLeft"]
            else 100.0
        )
        resize_me_end_pct = 100.0 - resize_me_right_pct
        over_expanded = (width_delta > drag_dx * 3) or (resize_me_end_pct > cramped_left_pct)

        print(
            f"DEBUG before_scroll={before_drag['scrollLeft']:.1f}, "
            f"during_drag={scroll_positions_during_drag}, "
            f"after_scroll={after_release['scrollLeft']:.1f}, "
            f"width_delta={width_delta:.1f} (drag_dx={drag_dx})",
            file=sys.stderr,
        )

        if scroll_jumped_to_zero_on_release or scroll_jumped_to_zero_during_drag or over_expanded:
