                        const allCards = trick.querySelectorAll('.hk-tcard');
                        const isLead = allCards.length === 1;
                        if (isLead) window.__qa.leadSeen = true;

                        const r = card.getBoundingClientRect();
                        let maxW = r.width;
                        const back = card.querySelector('.ch-turnback');
                        if (back) {
                            const br = back.getBoundingClientRect();
                            if (br.width > maxW) maxW = br.width;
                        }
                        if (maxW > window.__qa.maxWidth) window.__qa.maxWidth = maxW;
                        if (isLead && maxW > window.__qa.maxLeadWidth) window.__qa.maxLeadWidth = maxW;
                        if (maxW > 0 && maxW < window.innerWidth * 0.3) {
                            window.__qa.normalWidth = maxW;
                        }
                        if (maxW > window.innerWidth * 0.5) {
                            window.__qa.oversized = true;
                            if (isLead) window.__qa.leadOversized = true;
                        }
                    }
                }
                requestAnimationFrame(sample);
            }
            requestAnimationFrame(sample);
        }""")

        # Play through hands until teammate leads a trick (or timeout after 45s)
