import sys
from playwright.sync_api import sync_playwright

URL = "http://localhost:5173/"
SCREENSHOT_PATH = "/workspace/repro_datepicker5573.png"


def main():
    save_screenshot = "--screenshot" in sys.argv

    with sync_playwright() as p:
        browser = p.chromium.launch(
            executable_path="/usr/bin/google-chrome",
            headless=True,
        )
        page = browser.new_page(viewport={"width": 1280, "height": 900})

        # Step 1: Navigate to http://localhost:5173/
        page.goto(URL, wait_until="networkidle", timeout=60000)

        section = page.locator("#example-year-picker")
        section.wait_for(state="visible", timeout=30000)
        section.scroll_into_view_if_needed()

        year_input = section.locator(".example__preview input").first
        year_input.wait_for(state="visible", timeout=15000)

        initial_val = year_input.input_value()

        # Step 2: Click Year Picker text input
        year_input.click()

        popup = section.locator(".react-datepicker__year-wrapper")
        popup.wait_for(state="visible", timeout=10000)

        # Step 3: Delete input value using Backspace until empty
        for _ in range(len(initial_val) + 2):
            if year_input.input_value() == "":
                break
            page.keyboard.press("Backspace")
            page.wait_for_timeout(50)

        assert year_input.input_value() == "", f"Expected empty input, got {year_input.input_value()!r}"

        # Step 4: Observe Year Picker popup immediately after clearing
        after_clear = page.evaluate("""() => {
            const section = document.querySelector('#example-year-picker');
            const items = Array.from(section.querySelectorAll('.react-datepicker__year-text'));
            const selected = items.filter(el => el.classList.contains('react-datepicker__year-text--selected'));
            return {
                total: items.length,
                selectedCount: selected.length,
                years: items.map(el => el.textContent.trim()),
                selectedYears: selected.map(el => el.textContent.trim()),
            };
        }""")

        # Step 5: Click empty area above the Year Picker text input to close the popup
        heading = section.locator("h2.example__heading")
        heading.click()
        popup.wait_for(state="hidden", timeout=10000)

        # Step 6: Click the empty Year Picker text input to reopen the popup
        year_input.click()
        popup.wait_for(state="visible", timeout=10000)

        # Step 7: Observe Year Picker popup after reopening
        after_reopen = page.evaluate("""() => {
            const section = document.querySelector('#example-year-picker');
            const items = Array.from(section.querySelectorAll('.react-datepicker__year-text'));
            const selected = items.filter(el => el.classList.contains('react-datepicker__year-text--selected'));
            const bgColors = selected.map(el => getComputedStyle(el).backgroundColor);
            return {
                total: items.length,
                selectedCount: selected.length,
                years: items.map(el => el.textContent.trim()),
                selectedYears: selected.map(el => el.textContent.trim()),
                bgColors: Array.from(new Set(bgColors)),
            };
        }""")

        if save_screenshot:
            section.scroll_into_view_if_needed()
            page.screenshot(path=SCREENSHOT_PATH)

        browser.close()

        print(f"initial_val={initial_val!r}")
        print(f"after_clear={after_clear}")
        print(f"after_reopen={after_reopen}")

        bug_after_clear = (
            after_clear["total"] > 0
            and after_clear["selectedCount"] == after_clear["total"]
        )
        bug_after_reopen = (
            after_reopen["total"] > 0
            and after_reopen["selectedCount"] == after_reopen["total"]
        )

        if bug_after_clear and bug_after_reopen:
            print("BUG_PRESENT")
        else:
            print("BUG_ABSENT")


if __name__ == "__main__":
    main()

